import { phase } from '/tmp/probe/p.mjs';
import { readFileSync } from 'node:fs';

// usage: node drv.mjs <casesfile.json> [lang] [--raw]
// cases file: array of code snippets (strings). Each is wrapped in ```<lang> ... ```
const file = process.argv[2];
const lang = process.argv[3] || 'javascript';
const raw = process.argv.includes('--raw');
const cases = JSON.parse(readFileSync(file, 'utf8'));

const PRE = '<div class="codehilite"><pre><span></span><code>';
const POST = '</code></pre></div>';

for (const code of cases) {
  const md = '```' + lang + '\n' + code + '\n```';
  let out = phase('e', md);
  if (!raw) {
    if (out.startsWith(PRE) && out.endsWith(POST)) out = out.slice(PRE.length, out.length - POST.length);
    else out = '!!UNEXPECTED!! ' + out;
  }
  console.log('IN  ' + JSON.stringify(code));
  console.log('OUT ' + JSON.stringify(out));
}

